import{_ as a}from"./chunks/node_ace_list.B_jsqVlM.js";import{_ as i,o as e,c as t,a0 as l}from"./chunks/framework.DqMqoJl9.js";const g=JSON.parse('{"title":"命令行与 REPL","description":"在 DevShow React 教程中学习使用 AdonisJS Ace CLI 和 REPL 来生成文件并与应用交互。","frontmatter":{"description":"在 DevShow React 教程中学习使用 AdonisJS Ace CLI 和 REPL 来生成文件并与应用交互。"},"headers":[],"relativePath":"start/tutorial/react/cli_and_repl.md","filePath":"start/tutorial/react/cli_and_repl.md","lastUpdated":null}'),p={name:"start/tutorial/react/cli_and_repl.md"};function n(h,s,d,k,r,o){return e(),t("div",null,[...s[0]||(s[0]=[l('<h1 id="命令行与-repl" tabindex="-1">命令行与 REPL <a class="header-anchor" href="#命令行与-repl" aria-label="Permalink to &quot;命令行与 REPL&quot;">​</a></h1><p>你可能想知道为什么我们要介绍 CLI 和 REPL，而不是直接进入功能构建。原因如下：在整个教程中，你会不断使用 Ace 命令来生成控制器、模型和其他文件。现在熟悉 CLI 可以避免以后打断我们的流程。</p><p>更重要的是，<a href="./../../../guides/ace/repl.html">REPL</a> 将成为我们实验模型和数据库的游乐场。当我们在后续章节探索数据库查询、过滤器和关系时，我们会使用 REPL 来尝试各种操作。它是一个一次性的环境，让我们可以专注于学习概念，而无需构建完整功能的繁琐过程。</p><h2 id="探索可用命令" tabindex="-1">探索可用命令 <a class="header-anchor" href="#探索可用命令" aria-label="Permalink to &quot;探索可用命令&quot;">​</a></h2><p>让我们先看看 AdonisJS 提供了哪些命令。在终端中运行以下命令。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span></span></code></pre></div><p>你应该会看到类似这样的内容：</p><p><img src="'+a+`" alt="node ace list"></p><p>注意命令是如何分组的？</p><ul><li><code>make:*</code> 命令帮助你生成文件。</li><li><code>migration:*</code> 命令帮助你运行和回滚数据库迁移。</li><li><code>db:*</code> 命令处理数据库填充，等等。</li></ul><p>想了解某个特定命令的更多信息？只需在末尾加上 <code>--help</code>。这会显示该命令能做的所有事情，包括你可以传递给它的任何选项。</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> make:controller</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre></div><h2 id="使用-repl" tabindex="-1">使用 REPL <a class="header-anchor" href="#使用-repl" aria-label="Permalink to &quot;使用 REPL&quot;">​</a></h2><p>REPL 将在整个教程中作为我们的实验游乐场。让我们通过为 DevShow Web 应用创建和查询用户来探索如何使用它。</p><h3 id="启动-repl-并加载模型" tabindex="-1">启动 REPL 并加载模型 <a class="header-anchor" href="#启动-repl-并加载模型" aria-label="Permalink to &quot;启动 REPL 并加载模型&quot;">​</a></h3><p>首先，启动 REPL：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ace</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> repl</span></span></code></pre></div><p>REPL 启动后，使用 <code>loadModels()</code> 辅助函数加载所有模型。REPL 提供了多个像这样的内置辅助函数，让实验更容易。这个辅助函数会让你的所有模型在 <code>models</code> 命名空间下可用。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> loadModels</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 访问 user 模型</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">models.user</span></span></code></pre></div><h3 id="创建用户" tabindex="-1">创建用户 <a class="header-anchor" href="#创建用户" aria-label="Permalink to &quot;创建用户&quot;">​</a></h3><p>让我们使用 <code>User</code> 模型（存储在 <code>app/models/user.ts</code> 文件中）创建几个用户，以便稍后登录我们的应用。<code>create</code> 方法接受模型属性作为对象，将它们持久化到数据库并返回一个模型实例。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> models.user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ fullName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Harminder Virk&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, email: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;virk@adonisjs.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, password: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;secret&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><p>让我们再创建一个用户。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> models.user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">create</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">({ fullName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Jane Doe&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, email: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;jane@example.com&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, password: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;secret&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><h3 id="获取所有用户" tabindex="-1">获取所有用户 <a class="header-anchor" href="#获取所有用户" aria-label="Permalink to &quot;获取所有用户&quot;">​</a></h3><p>现在你已经创建了几个用户，让我们使用 <code>all</code> 方法获取它们。该方法会执行 <code>SELECT *</code> 查询，并返回一个包含两个用户的数组。每个用户都是 User 模型实例，而不是普通的 JavaScript 对象。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> models.user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h3 id="查找并删除用户" tabindex="-1">查找并删除用户 <a class="header-anchor" href="#查找并删除用户" aria-label="Permalink to &quot;查找并删除用户&quot;">​</a></h3><p>你可以使用 <code>find</code> 方法通过给定的 ID 查找用户。返回值是 User 模型的实例，或者 <code>null</code>（如果未找到用户）。</p><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> user</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> models.user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">find</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user.id</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// 1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user.email</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// &#39;virk@adonisjs.com&#39;</span></span></code></pre></div><p>你可以通过在 User 实例上调用 <code>delete</code> 方法来删除此用户。</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">delete</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user.$isDeleted </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// true</span></span></code></pre></div><p>如果你再次列出所有用户，应该只会看到 Jane 还在：</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> models.user.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">all</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">()</span></span></code></pre></div><h3 id="退出-repl" tabindex="-1">退出 REPL <a class="header-anchor" href="#退出-repl" aria-label="Permalink to &quot;退出 REPL&quot;">​</a></h3><p>探索完成后，输入 <code>.exit</code> 或按 <code>Ctrl+D</code> 离开 REPL 并返回终端。</p>`,36)])])}const u=i(p,[["render",n]]);export{g as __pageData,u as default};
